WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (391::BIGINT, 'Excelente profesora, reprobé el curso por vago. Es importante prestar mucha atención durante las clases y si es posible anotar todo. Los ejercicios que resuelve en clase tienen alta dificultad, sus tareas son regulares y deja bastante material.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-17T00:00:00+00:00'::TIMESTAMPTZ, 'f389aa659ead8c49f8fd2267452f80452b13e829033299045274a39f2dda37b1'::TEXT, ARRAY[1267]::BIGINT[]),
    (391::BIGINT, 'Explica bien pero es muy desorganizada al estar escibiendo en la pizarra al punto de que lo enreda a uno, hace los examenes muy duros, no califica ni suave ni duro pero tengalo por seguro de que ella no esta para ayudar al estudiante, es muy cerrada en ese aspecto de que no ayuda. Hay que ponerle.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2026-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'b0a86cc9ff2f5155fe0b0d0c55a02e352795714ed76f2833bfd3b9f7cbd64428'::TEXT, ARRAY[1257]::BIGINT[]),
    (391::BIGINT, 'La profe es demasiado buena persona y se nota que quiere que uno aprenda. Califica duro y los exámenes también son algo rudos. En clases llega a ser desorganizada. De igual forma meta con ella pq lo va a preparar muy bien.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'efac4b647c9b31a181d70f973aca6633d00047771d26b0aa90d5255bac46b25e'::TEXT, ARRAY[1257]::BIGINT[]),
    (391::BIGINT, 'La profe hace los examenes un poco dificiles, pero nada que no haya explicado en clases. Es la mejor para aprender de CC y ademas te prepara para CA. Es un amor de persona y siempre es muy alegre.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2026-01-12T00:00:00+00:00'::TIMESTAMPTZ, 'a9a8d4b0621730e7fd0332acd19fed60c6281d5de315500e0030af1051c8351b'::TEXT, ARRAY[1257]::BIGINT[]),
    (391::BIGINT, 'Admiro a esta profesora, transmite mucha pasión por enseñar y por la electrónica. Tiene una personalidad y actitud muy bonita, enseña muy bien. Eso si, sus clases son MUY densas en materia y complejas, las tareas que deja son super largas e igual de complejas, pero ayuda a aprender bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Deja trabajos largos']::TEXT[], '2025-12-14T00:00:00+00:00'::TIMESTAMPTZ, '3b13fee9cf5b279858f3eb0abb5f6de000b3cfbd66da3a6c173a59f8bf30c001'::TEXT, ARRAY[1267]::BIGINT[]),
    (391::BIGINT, 'La mejor de todos los tiempos, se nota que quiere a los estudiantes y sabe muuuucho del tema, se aprende bastante, para CC la recomiendo mas porque va a sacar buenas bases llevando con ella aunque sea mas dificil, 100000/10'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-13T00:00:00+00:00'::TIMESTAMPTZ, '46db44b7045b067409cb662cf7fdce363f98490adcf768355c5a365f08815d51'::TEXT, ARRAY[1257, 1267]::BIGINT[]),
    (391::BIGINT, 'La profe es simplemente la cabra, de las mejores profes de la escuela. Si quieren aprender CC lleven con ella ya que explica muy muy bien y hace bastantes ejercicios, si llega a calificar "duro" pero justo la verdad y si usted le reclama si le da los puntos justos y en consulta ayuda a entender.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2025-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'd4b27f9ad2e88fac0956ffd73d70b3dc2887791c2716e1288c3a6c75a55e0c56'::TEXT, ARRAY[1257]::BIGINT[]),
    (391::BIGINT, 'Excelente profe, CC es un curso pesado (sobre todo con ella) pero uno definitivamente aprende bien toda la materia. Paola lo prepara a uno muy bien para los próximos cursos. La recomiendo full'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Muchos exámenes', 'Clases excelentes']::TEXT[], '2025-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'e097328818c1da05d0907f75b873f66ca5abb2a59236813917603ecadcb11cf9'::TEXT, ARRAY[1257]::BIGINT[]),
    (391::BIGINT, 'El curso en sí es rudo y hay que estudiar mucho. Deja bastantes tareas que en el momento parecen tediosas pero ayudan bastante para estudiar'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-08-04T00:00:00+00:00'::TIMESTAMPTZ, '5d94e64dcb4ba7136aad94fc085c47ba4186ae9a001c629d2745119bdf94b874'::TEXT, ARRAY[1267]::BIGINT[]),
    (391::BIGINT, 'Las clases son excelentes, explica los contenidos de manera muy clara y se adentra un poco mas en la materia para comprenderla a profundidad. Hace bastantes ejercicios y se nota que le apasiona la materia. Califica de manera muy justa. Muy buena profe :D'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2025-07-23T00:00:00+00:00'::TIMESTAMPTZ, '8065f1212d0724f39aea45c9faf342f638782ed729db32f05660d7690799d721'::TEXT, ARRAY[1267]::BIGINT[]),
    (391::BIGINT, 'El curso es dificil, ella no es muy organizada cuando escribe en la pantalla y las clases suelen ser algo aburridas. Aún así, explica claro y siempre está dispuesta a ayudar.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, '27ae87838f44561d824d777b009f7aac4c2b15d140f83854e9ba9412f02bce10'::TEXT, ARRAY[1267]::BIGINT[]),
    (391::BIGINT, 'La profe es demasiado buena explicando y le interesa que usted aprenda, pero así como enseña así califica. Si le puede dedicar su buen tiempo a la materia, se la recomiendo, pero si no es así mejor busque otra opción para que no sufra.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Exámenes retadores']::TEXT[], '2025-07-05T00:00:00+00:00'::TIMESTAMPTZ, 'c932f615a13c35b8a242e7500cc8fd240784d23d88745c0c16e9f90e96213b5a'::TEXT, ARRAY[1257]::BIGINT[]),
    (391::BIGINT, 'Aunque si es cierto que califica duro, sus clases las imparte con mucho cariño y hace preguntas para ver si uno entiende. La recomiendo si es que llevan el curso por primera vez, o de verdad quieren aprender. Lleven tutorías para que no hagan las tareas.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2025-07-01T00:00:00+00:00'::TIMESTAMPTZ, '499d9cff0c2951c35d05681f3cb2dcccfd13c36a0b3514cb72632b4cd02f00d1'::TEXT, ARRAY[1257]::BIGINT[]),
    (391::BIGINT, 'La materia ya de por si es pesada, pero ella intenta todo lo posible porque entiendan, las tareas las califica duro, pero buena profe en general'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-12-06T00:00:00+00:00'::TIMESTAMPTZ, '808d4b5622bcdf3dfafe1b4e8b116f5e33a53e84475ae6231434826ea6e953c6'::TEXT, ARRAY[1267]::BIGINT[]),
    (391::BIGINT, 'Simplemente la mejor profe para CC, puede parecer que complica el curso pero uno aprende bastante. Antes de cada examen asigna una lista de ejercicios y a veces hace sesiones de practica, además de que le importa que uno aprenda entonces explica las veces que sea necesario'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'd7904c342ca1ec63050b1fa705bda2d79710aa516f420755862301596d3a2cf3'::TEXT, ARRAY[1257]::BIGINT[]),
    (391::BIGINT, 'La profe es muy buena gente y realmente le importa que usted aprenda, brinda demasiado apoyo y la manera que califica es muy considerada, explica de una manera muy clara, parece que speedrunea todo el curso pero enserio es muy buena, la mejor profe para cc'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '5b72ef753e7f6429a6a00f7634a8b3addae5ea1b414ef5c82853dffadf46378f'::TEXT, ARRAY[1257]::BIGINT[]),
    (391::BIGINT, 'Sin duda la mejor profe con la que me he topado en el tec, explica muy bien, si le piden da clases extras antes de los exámenes y califica de manera justa, da bastantes puntos por procedimiento. En serio se nota que ama su trabajo y logra hacer que a uno le encante la materia. DIOSA'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '2bbb8de14e5c701789cae0358b4c37e687321c8c48183084e25596164dcd8f58'::TEXT, ARRAY[1257]::BIGINT[]),
    (391::BIGINT, 'Excelente profesora, explica muy bien y se le entiende todo. En si, el curso es sencillo mientras realices ejercicios. Yo recomiendo hacer muchos ejercicios que involucre fuentes dependientes, ya que siempre aparecerán estos en los exámenes.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'bac83337ff3bab44994f9a50308aa146fe40adbc3613f9a3861a6c0665f70f6c'::TEXT, ARRAY[1257]::BIGINT[]),
    (391::BIGINT, 'La profe es muy buena, siempre trata de ayudar y se aprende mucho en el curso, solamente los examenes pueden ser un poco duros, pero con estudiar se va bien'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'd9d2babd9e540847c2f23704c74ffe54cae17b53ade8449afbfd91088254cfcb'::TEXT, ARRAY[1257]::BIGINT[]),
    (391::BIGINT, 'Buena profe y buena gente. En sí el curso es complicado y hay que dedicarle tiempo, si lleva bloque completo pienselo un poco. La evaluación es 90% examenes, pero sí lleva tutorias es 80% examenes, por lo que es recomendable meter tutorias para que no le castiguen mucho los examenes.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2024-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'c648f65f0005b6ef33b11b41696e4643c0b00f15fb5c3cb8bf395e90ff2b14b8'::TEXT, ARRAY[1257]::BIGINT[]),
    (391::BIGINT, 'Es una buena opción, explica bastante claro los temas y ademas, realiza mucha práctica. Los exámenes son duros pero se pueden sacar si se estudia bastante. En general, si quiere aprender de una buena forma y pasar "bien", llevelo con ella.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2024-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'b22672a90d59d4c96f05184f578dd88d845c9bf662389663e397b98fe561e138'::TEXT, ARRAY[1267]::BIGINT[]),
    (391::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-11T00:00:00+00:00'::TIMESTAMPTZ, '2f8905f13cc8aa0f46e4a488f89640785e492500f2bfeb64b3c73bd28bbab220'::TEXT, ARRAY[1267]::BIGINT[]),
    (391::BIGINT, 'Excelente profesora, las clases tienden a ser muy aburridas por las largas presentaciones, pero cuando explica los ejercicios no quedan dudas, busca la manera de facilitar el entendimiento de la materia, califica con piedad, ayuda demasiado en consulta.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'c5ceb0bde7ef435794c32cd21580eedc2b9419a34c409413e18f3b1a513237c2'::TEXT, ARRAY[1267]::BIGINT[]),
    (391::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'a5743ed29ed13e6d643d2209a54aa7dd0b121c73f5c931610370da9f5f151564'::TEXT, ARRAY[1267]::BIGINT[]),
    (391::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'df18d4382ba46ae58fe9c9720d6abfe11967b48f96ef3a82bd5c24c62e14bf51'::TEXT, ARRAY[1267]::BIGINT[]),
    (391::BIGINT, 'Es la profesora con la que cualquier persona puede soñar. Es excelente explicando, profundiza mucho y de vez en cuando da charlas de motivación. Le interesa que todos aprendan y que salgan bien, de esos pocos profes que se emocionan de ver buenas notas. Es el amor hecho profesora, excelente persona,'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-26T00:00:00+00:00'::TIMESTAMPTZ, '06292acec55ffda7727d7435024bdf99c79c49b15d5a78a17b0c5fb2a9452c9a'::TEXT, ARRAY[1267]::BIGINT[]),
    (391::BIGINT, 'Muy buena profe.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-23T00:00:00+00:00'::TIMESTAMPTZ, '19bdd34744f87e3ca9605b85fd06028464316f9373f6fcd20fd1c220453986cd'::TEXT, ARRAY[1267]::BIGINT[]),
    (391::BIGINT, 'Excelente profesora'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'f5fd11fb406a238cfad80c971dede6337a4b665e32e61bdabe2b56ca6234ca53'::TEXT, ARRAY[1267]::BIGINT[]),
    (391::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '9dc1ca9c95a99157725b2ee364cf0b266c425793838b4bbe3cff5903d71f5066'::TEXT, ARRAY[1267]::BIGINT[]),
    (391::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '270fafe21e3ef7749031fc7ca7787ea7e7c99c05adc81b623659d8cbeafe43eb'::TEXT, ARRAY[1267]::BIGINT[]),
    (391::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '0fd270b38db3f45b297364f711541796677d9d6eeb722d57c747cde41d28b6b9'::TEXT, ARRAY[1267]::BIGINT[]),
    (391::BIGINT, 'No es fácil, pero que Diosa para explicar esta profesora!!!! Para mi una de las mejores profesoras, ademas esta guapilla.. xD!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '7d226032abb9d69889371d3de4cd5473486b071c60f1280aef552a4e20d4fe67'::TEXT, ARRAY[1267]::BIGINT[]),
    (391::BIGINT, 'La mejor profesora que he tenido en el TEC. Explica súper bien, muy atenta, como persona excelente.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'fc3d3dc1f40a9cc4b9500648b7603d1f1276d3f2362ce2b0890ae9e4518e003d'::TEXT, ARRAY[1267]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
